// Page behaviour: data from docs/site_data.json (generated by scripts/build_site_data.py from the tested code),
// animated number tickers, spotlight cards, scroll reveals (GSAP ScrollTrigger), KaTeX equations, capability matrix.
document.documentElement.classList.remove("no-js");
const fmt = (x, d) => (Math.abs(x) >= 1e5 || (Math.abs(x) > 0 && Math.abs(x) < 1e-3)) ? x.toExponential(d ?? 2) : x.toFixed(d ?? 1);
const get = (o, path) => path.split(".").reduce((a, k) => (a == null ? a : a[k]), o);

function spotlight() {
  document.querySelectorAll(".card").forEach((c) => c.addEventListener("pointermove", (e) => {
    const r = c.getBoundingClientRect(); c.style.setProperty("--x", `${e.clientX - r.left}px`); c.style.setProperty("--y", `${e.clientY - r.top}px`);
  }));
}
function tickers(data) {
  document.querySelectorAll("[data-num]").forEach((el) => {
    const v = get(data, el.dataset.num); if (typeof v !== "number") return;
    const d = el.dataset.dec !== undefined ? +el.dataset.dec : 1;
    if (window.gsap && !matchMedia("(prefers-reduced-motion: reduce)").matches) {
      const o = { v: 0 };
      gsap.to(o, { v, duration: 1.8, ease: "power3.out", scrollTrigger: { trigger: el, start: "top 90%" }, onUpdate: () => (el.textContent = fmt(o.v, d)) });
    } else el.textContent = fmt(v, d);
  });
  document.querySelectorAll("[data-val]").forEach((el) => { const v = get(data, el.dataset.val); if (typeof v === "number") el.textContent = fmt(v, el.dataset.dec !== undefined ? +el.dataset.dec : 2); });
}
function matrix(data) {
  const host = document.getElementById("matrix"); if (!host) return;
  const bases = Object.keys(data.baselines_round_trip_s);
  const human = (s) => s < 1 ? (s * 1e3).toFixed(1) + " ms" : s < 120 ? s.toFixed(1) + " s" : s < 7200 ? (s / 60).toFixed(1) + " min" : (s / 3600).toFixed(1) + " h";
  let h = "<table><thead><tr><th>Memory</th><th>Lifetime</th><th>Efficiency</th><th>Useful for (F ≥ 2/3)</th>";
  bases.forEach((b) => (h += `<th>${b}<br><span style="color:var(--faint)">${human(data.baselines_round_trip_s[b])}</span></th>`));
  h += "</tr></thead><tbody>";
  data.memories.forEach((m) => {
    h += `<tr><td>${m.name}</td><td>${human(m.lifetime_s)}</td><td>${(100 * m.efficiency).toFixed(1)} %</td><td>${human(m.crossover_s)}</td>`;
    bases.forEach((b) => (h += m.survives[b] ? '<td class="yes">✓</td>' : '<td class="no">·</td>'));
    h += "</tr>";
  });
  host.innerHTML = h + "</tbody></table>";
}
function reveals() {
  if (!window.gsap || !window.ScrollTrigger || matchMedia("(prefers-reduced-motion: reduce)").matches) {
    document.querySelectorAll(".reveal").forEach((e) => (e.style.cssText = "opacity:1;transform:none;filter:none")); return;
  }
  gsap.registerPlugin(ScrollTrigger);
  gsap.utils.toArray(".reveal").forEach((el, i) => gsap.to(el, { opacity: 1, y: 0, filter: "blur(0px)", duration: 0.9, ease: "power3.out", delay: (i % 4) * 0.06,
    scrollTrigger: { trigger: el, start: "top 88%" } }));
  gsap.from(".hero-inner > *", { opacity: 0, y: 30, filter: "blur(8px)", stagger: 0.12, duration: 1.1, ease: "power3.out" });
}
function math() {
  if (window.renderMathInElement) renderMathInElement(document.body, { delimiters: [{ left: "$$", right: "$$", display: true }, { left: "\\(", right: "\\)", display: false }], throwOnError: false });
}
async function main() {
  spotlight(); reveals(); math();
  try {
    const data = await (await fetch("site_data.json", { cache: "no-cache" })).json();
    if (window.QLLEphemeris) window.QLLEphemeris.configure(data);
    tickers(data); matrix(data);
    const s = data.status || {};
    document.querySelectorAll("[data-status]").forEach((el) => { if (s[el.dataset.status] !== undefined) el.textContent = s[el.dataset.status]; });
    if (window.ScrollTrigger) ScrollTrigger.refresh();
  } catch (e) { console.warn("site_data.json unavailable", e); }
}
main();
